199	// ExtractSpawnedAgentIDs extracts agent IDs from Task tool results in a transcript.
200	// When a Task tool completes, the tool_result contains "agentId: <id>" in its content.
201	// Returns a map of agentID -> toolUseID for all spawned agents.
202	func ExtractSpawnedAgentIDs(transcript []TranscriptLine) map[string]string {
203		agentIDs := make(map[string]string)
204	
205		for _, line := range transcript {
206			if line.Type != "user" {
207				continue
208			}
209	
210			// Parse as array of content blocks (tool results)
211			var contentBlocks []struct {
212				Type      string          `json:"type"`
213				ToolUseID string          `json:"tool_use_id"`
214				Content   json.RawMessage `json:"content"`
215			}
216	
217			var msg struct {
218				Content json.RawMessage `json:"content"`
219			}
220			if err := json.Unmarshal(line.Message, &msg); err != nil {
221				continue
222			}
223	
224			if err := json.Unmarshal(msg.Content, &contentBlocks); err != nil {
225				continue
226			}
227	
228			for _, block := range contentBlocks {
229				if block.Type != "tool_result" {
230					continue
231				}
232	
233				// Content can be a string or array of text blocks
234				var textContent string
235	
236				// Try as array of text blocks first
237				var textBlocks []struct {
238					Type string `json:"type"`
239					Text string `json:"text"`
240				}
241				if err := json.Unmarshal(block.Content, &textBlocks); err == nil {
242					var textContentSb361 strings.Builder
243					for _, tb := range textBlocks {
244						if tb.Type == "text" {
245							textContentSb361.WriteString(tb.Text + "\n")
246						}
247					}
248					textContent += textContentSb361.String()
249				} else {
250					// Try as plain string
251					var str string
252					if err := json.Unmarshal(block.Content, &str); err == nil {
253						textContent = str
254					}
255				}
256	
257				// Look for agentId in the text
258				if agentID := extractAgentIDFromText(textContent); agentID != "" {
259					agentIDs[agentID] = block.ToolUseID
260				}
261			}
262		}
263	
264		return agentIDs
265	}
