290	// CalculateTotalTokenUsage calculates token usage for a turn, including subagents.
291	// It parses the main transcript bytes from startLine, extracts spawned agent IDs,
292	// and calculates their token usage from transcript files in subagentsDir.
293	func (c *ClaudeCodeAgent) CalculateTotalTokenUsage(transcriptData []byte, startLine int, subagentsDir string) (*agent.TokenUsage, error) {
294		if len(transcriptData) == 0 {
295			return &agent.TokenUsage{}, nil
296		}
297	
298		// Slice to the relevant portion and parse
299		sliced := transcript.SliceFromLine(transcriptData, startLine)
300		parsed, err := transcript.ParseFromBytes(sliced)
301		if err != nil {
302			return nil, fmt.Errorf("failed to parse transcript: %w", err)
303		}
304	
305		// Calculate token usage from parsed transcript
306		mainUsage := CalculateTokenUsage(parsed)
307	
308		// Extract spawned agent IDs from the same parsed transcript
309		agentIDs := ExtractSpawnedAgentIDs(parsed)
310	
311		// Calculate subagent token usage (skip when subagentsDir is empty to avoid reading from cwd)
312		if len(agentIDs) > 0 && subagentsDir != "" {
313			subagentUsage := &agent.TokenUsage{}
314			for agentID := range agentIDs {
315				agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
316				agentUsage, err := CalculateTokenUsageFromFile(agentPath, 0)
317				if err != nil {
318					// Agent transcript may not exist yet or may have been cleaned up
319					continue
320				}
321				subagentUsage.InputTokens += agentUsage.InputTokens
322				subagentUsage.CacheCreationTokens += agentUsage.CacheCreationTokens
323				subagentUsage.CacheReadTokens += agentUsage.CacheReadTokens
324				subagentUsage.OutputTokens += agentUsage.OutputTokens
325				subagentUsage.APICallCount += agentUsage.APICallCount
326			}
327			if subagentUsage.APICallCount > 0 {
328				mainUsage.SubagentTokens = subagentUsage
329			}
330		}
331	
332		return mainUsage, nil
333	}
