112	// droppedTypes are JSONL entry types that carry no parser-relevant data.
113	var droppedTypes = map[string]bool{
114		"progress":              true,
115		"file-history-snapshot": true,
116		"queue-operation":       true,
117		"system":                true,
118	}
119	
120	// userAliases maps JSONL type/role values to the canonical "user" kind.
121	// Covers Claude Code ("user", "human") and Cursor ("user" via "role" field).
122	var userAliases = map[string]bool{
123		transcript.TypeUser: true,
124		"human":             true,
125	}
126	
127	// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
128	// JSONL transcript line. It checks the "type" field, then falls back to "role".
129	// Returns "" for unrecognised or dropped entries.
130	func normalizeKind(raw map[string]json.RawMessage) string {
131		kind := unquote(raw["type"])
132		if kind == "" {
133			kind = unquote(raw["role"])
134		}
135	
136		if droppedTypes[kind] {
137			return ""
138		}
139		if userAliases[kind] {
140			return transcript.TypeUser
141		}
142		if kind == transcript.TypeAssistant {
143			return transcript.TypeAssistant
144		}
145		return ""
146	}
