148	// linePreprocessor transforms a parsed JSONL line before conversion.
149	type linePreprocessor func(map[string]json.RawMessage) map[string]json.RawMessage
150	
151	// parsedEntry is an intermediate representation of a JSONL line used during
152	// the two-pass compact conversion.
153	type parsedEntry struct {
154		kind         string // "user" or "assistant"
155		ts           json.RawMessage
156		id           string            // message ID (assistant only)
157		userID       string            // prompt ID (user only, e.g. Claude's promptId)
158		inputTokens  int               // API input tokens (assistant only)
159		outputTokens int               // API output tokens (assistant only)
160		content      json.RawMessage   // stripped assistant content array, or nil
161		userText     string            // extracted user text
162		userImages   []json.RawMessage // image blocks from user messages
163		toolResults  []toolResultEntry // user tool_result entries
164	}
