166	// compactJSONL converts JSONL transcripts (Claude Code, Cursor) into the
167	// transcript.jsonl format.
168	func compactJSONL(content []byte, opts MetadataFields) ([]byte, error) {
169		return compactJSONLWith(content, opts, nil)
170	}
171	
172	func compactJSONLWith(content []byte, opts MetadataFields, preprocess linePreprocessor) ([]byte, error) {
173		base := newTranscriptLine(opts)
174	
175		// Pass 1: parse all lines into intermediate entries.
176		entries, err := parseJSONLEntries(content, preprocess)
177		if err != nil {
178			return nil, err
179		}
180	
181		// Pass 2: merge and emit.
182		var result []byte
183		for i := 0; i < len(entries); i++ {
184			e := entries[i]
185	
186			switch e.kind {
187			case transcript.TypeAssistant:
188				// Merge consecutive assistant entries with the same message ID.
189				merged := e
190				for i+1 < len(entries) && entries[i+1].kind == transcript.TypeAssistant && entries[i+1].id == e.id {
191					i++
192					merged = mergeAssistantEntries(merged, entries[i])
193				}
194	
195				// Look ahead for user tool_result entries to inline.
196				if i+1 < len(entries) && entries[i+1].kind == transcript.TypeUser && hasToolResults(entries[i+1]) {
197					userEntry := entries[i+1]
198					merged = inlineToolResults(merged, userEntry)
199					i++ // consume the user tool_result entry
200	
201					// If the consumed user entry also had text or image content, emit it
202					// as a separate user line after the assistant.
203					if userEntry.userText != "" || len(userEntry.userImages) > 0 {
204						emitAssistant(&result, base, merged)
205						emitUser(&result, base, userEntry)
206						continue
207					}
208				}
209	
210				if isEmptyContentArray(merged.content) {
211					continue
212				}
213	
214				emitAssistant(&result, base, merged)
215	
216			case transcript.TypeUser:
217				// User entries that are purely tool results were already consumed
218				// by the assistant look-ahead above. If we reach one here it was
219				// not preceded by an assistant with a matching tool_use, so emit
220				// it only if it has text or image content.
221				if hasToolResults(e) && e.userText == "" && len(e.userImages) == 0 {
222					continue
223				}
224				emitUser(&result, base, e)
225			}
226		}
227	
228		return result, nil
229	}
230	
231	func emitAssistant(result *[]byte, base transcriptLine, e parsedEntry) {
232		line := base
233		line.Type = transcript.TypeAssistant
234		line.TS = e.ts
235		line.ID = e.id
236		line.InputTokens = e.inputTokens
237		line.OutputTokens = e.outputTokens
238		line.Content = e.content
239		appendLine(result, line)
240	}
241	
242	func emitUser(result *[]byte, base transcriptLine, e parsedEntry) {
243		var blocks []json.RawMessage
244	
245		// Text block (with optional prompt ID).
246		if e.userText != "" || len(e.userImages) == 0 {
247			b, err := json.Marshal(userTextBlock{ID: e.userID, Text: e.userText})
248			if err != nil {
249				return
250			}
251			blocks = append(blocks, b)
252		}
253	
254		// Image blocks passed through verbatim.
255		blocks = append(blocks, e.userImages...)
256	
257		contentJSON, err := json.Marshal(blocks)
258		if err != nil {
259			return
260		}
261	
262		line := base
263		line.Type = transcript.TypeUser
264		line.TS = e.ts
265		line.Content = contentJSON
266		appendLine(result, line)
267	}
