269	// appendLine marshals a transcriptLine and appends it (with newline) to result.
270	func appendLine(result *[]byte, line transcriptLine) {
271		b, err := json.Marshal(line)
272		if err != nil {
273			return
274		}
275		*result = append(*result, b...)
276		*result = append(*result, '\n')
277	}
