361	// mergeAssistantEntries combines two assistant entries with the same message ID.
362	// Content arrays are concatenated; the later timestamp and token counts win
363	// (streaming fragments report cumulative usage, so the last fragment is final).
364	func mergeAssistantEntries(a, b parsedEntry) parsedEntry {
365		merged := a
366		merged.ts = b.ts
367		if b.inputTokens > 0 {
368			merged.inputTokens = b.inputTokens
369		}
370		if b.outputTokens > 0 {
371			merged.outputTokens = b.outputTokens
372		}
373	
374		var aBlocks, bBlocks []json.RawMessage
375		_ = json.Unmarshal(a.content, &aBlocks) //nolint:errcheck // best-effort merge
376		_ = json.Unmarshal(b.content, &bBlocks) //nolint:errcheck // best-effort merge
377		all := append(aBlocks, bBlocks...)      //nolint:gocritic // intentional append to new slice
378		if data, err := json.Marshal(all); err == nil {
379			merged.content = data
380		}
381	
382		return merged
383	}
