419	// buildToolResult constructs the compact result object for a tool_use block,
420	// including optional rich metadata (file, matchCount) when available.
421	func buildToolResult(tr toolResultEntry) json.RawMessage {
422		r := toolResultJSON{
423			Output:     tr.output,
424			Status:     "success",
425			MatchCount: tr.matchCount,
426		}
427		if tr.isError {
428			r.Status = toolResultStatusError
429		}
430		if tr.file != nil {
431			r.File = &toolResultFileJSON{
432				FilePath: tr.file.filePath,
433				NumLines: tr.file.numLines,
434			}
435		}
436		b, err := json.Marshal(r)
437		if err != nil {
438			return nil
439		}
440		return b
441	}
