443	// extractUsageTokens extracts input_tokens and output_tokens from a Claude
444	// message's "usage" object. Returns (0, 0) if usage is absent or malformed.
445	func extractUsageTokens(msg map[string]json.RawMessage) (inputTokens, outputTokens int) {
446		usageRaw, ok := msg["usage"]
447		if !ok {
448			return 0, 0
449		}
450		var usage struct {
451			InputTokens  int `json:"input_tokens"`
452			OutputTokens int `json:"output_tokens"`
453		}
454		if json.Unmarshal(usageRaw, &usage) != nil {
455			return 0, 0
456		}
457		return usage.InputTokens, usage.OutputTokens
458	}
