470	type toolResultEntry struct {
471		toolUseID string
472		output    string
473		isError   bool
474		// Rich metadata extracted from toolUseResult (optional).
475		file       *toolResultFile // Read/Edit: file path and line count
476		matchCount int             // Grep: number of matching files
477	}
478	
479	// toolResultFile carries structured file metadata from Read/Edit tool results.
480	type toolResultFile struct {
481		filePath string
482		numLines int // 0 if not available (e.g. Edit results)
483	}
484	
485	// enrichToolResults extracts structured metadata from a toolUseResult envelope
486	// and attaches it to the corresponding tool result entries.
487	//
488	// Claude Code's toolUseResult has different shapes per tool:
489	//   - Bash:  {stdout, stderr, interrupted, ...}
490	//   - Read:  {type:"text", file:{filePath, numLines, content, ...}}
491	//   - Grep:  {numFiles, numLines, filenames, content, mode}
492	//   - Edit:  {filePath, oldString, newString, structuredPatch, ...}
493	func enrichToolResults(results []toolResultEntry, tur map[string]json.RawMessage) []toolResultEntry {
494		// Bash-style: stdout provides the output text.
495		if stdout := unquote(tur["stdout"]); stdout != "" {
496			switch len(results) {
497			case 0:
498				// Keep compatibility with transcripts that only include toolUseResult.
499				results = append(results, toolResultEntry{output: stdout})
500			case 1:
501				results[0].output = stdout
502			}
503		}
504	
505		// Read-style: file object with filePath and numLines.
506		if fileRaw, ok := tur["file"]; ok {
507			var file struct {
508				FilePath string `json:"filePath"`
509				NumLines int    `json:"numLines"`
510			}
511			if json.Unmarshal(fileRaw, &file) == nil && file.FilePath != "" {
512				applyToSingleResult(results, func(tr *toolResultEntry) {
513					tr.file = &toolResultFile{filePath: file.FilePath, numLines: file.NumLines}
514				})
515			}
516		}
517	
518		// Edit-style: top-level filePath.
519		if filePath := unquote(tur["filePath"]); filePath != "" {
520			applyToSingleResult(results, func(tr *toolResultEntry) {
521				// Edit results don't have numLines.
522				tr.file = &toolResultFile{filePath: filePath}
523			})
524		}
525	
526		// Grep-style: numFiles as match count.
527		if numFilesRaw, ok := tur["numFiles"]; ok {
528			var n int
529			if json.Unmarshal(numFilesRaw, &n) == nil && n > 0 {
530				applyToSingleResult(results, func(tr *toolResultEntry) {
531					tr.matchCount = n
532				})
533			}
534		}
535	
536		return results
537	}
