539	// applyToSingleResult applies fn to the first (and expected only) tool result.
540	// toolUseResult is a single-tool envelope, so this is only meaningful when
541	// there's exactly one result entry.
542	func applyToSingleResult(results []toolResultEntry, fn func(*toolResultEntry)) {
543		if len(results) == 1 {
544			fn(&results[0])
545		}
546	}
