561	func scopeTranscriptForCheckpoint(fullTranscript []byte, startOffset int, agentType types.AgentType) []byte {
562		switch agentType {
563		case agent.AgentTypeGemini:
564			scoped, err := geminicli.SliceFromMessage(fullTranscript, startOffset)
565			if err != nil {
566				return nil
567			}
568			return scoped
569		case agent.AgentTypeOpenCode:
570			scoped, err := opencode.SliceFromMessage(fullTranscript, startOffset)
571			if err != nil {
572				return nil
573			}
574			return scoped
575		case agent.AgentTypeClaudeCode, agent.AgentTypeCursor, agent.AgentTypeFactoryAIDroid, agent.AgentTypeUnknown:
576			return transcript.SliceFromLine(fullTranscript, startOffset)
577		}
578		return transcript.SliceFromLine(fullTranscript, startOffset)
579	}
